const v = $('Validate').first().json; const o = $json.output;
const faq = {"faq-01":"Fill in the quote form on our website or call us. We reply within one business day and book a free roof assessment.","faq-02":"We install across Queensland and northern New South Wales. We do not currently install elsewhere.","faq-03":"A typical home system is installed in one to two days after approvals are in place.","faq-04":"Roughly 1.8 square metres per panel. A 6.6 kW system of 15 panels needs about 27 square metres of usable roof.","faq-05":"Panels carry a 25-year performance warranty, inverters 10 years, and our workmanship is covered for 5 years.","faq-06":"Yes. We lodge the grid connection application and the feed-in tariff paperwork on your behalf at no extra cost.","faq-07":"Yes. We offer 0 percent interest payment plans for up to 24 months through a partner lender, subject to approval.","faq-08":"Yes, if your inverter is battery-ready. We check this during the assessment and can retrofit a battery at any time.","faq-09":"Standard systems switch off during a blackout for safety. Only systems with a battery and backup gateway can supply power during an outage.","faq-10":"Rain usually keeps them clean. We suggest a gentle rinse once or twice a year if you are in a dusty area.","faq-11":"Our support team is available 8am to 5pm AEST, Monday to Friday. Emergencies are answered by phone 24/7.","faq-12":"Every system includes the Acme Solar app, which shows live and historical production and savings."};
const ok = !$json.error && o && ["sales_enquiry","support","billing","booking_change","complaint","spam","newsletter","other"].includes(o.category) && ['normal', 'urgent'].includes(o.urgency) && Array.isArray(o.faq_ids);
const text = v.subject + '\n' + v.body; const reasons = [];
const safety = new RegExp("\\b(burning|smoke|smoking|fire|flames?|sparks?|sparking|crackl\\w*|electric shock|shocked|exposed wires?|bare wires?|melt\\w*)\\b", 'i').test(text), legal = new RegExp("\\b(solicitor|lawyer|legal action|fair trading|ombudsman|tribunal|qcat|ncat|chargeback)\\b", 'i').test(text);
const category = ok ? o.category : 'unclassified';
let urgency = ok ? o.urgency : 'normal';
if (!ok) reasons.push($json.error ? 'ai_unavailable' : 'ai_output_unusable');
if (safety) { urgency = 'urgent'; reasons.push('safety_words'); }
if (legal) reasons.push('legal_words');
let route, draft = null;
if (ok && ['spam', 'newsletter'].includes(category) && !safety && !legal) route = 'no_action';
else if (!ok || urgency === 'urgent' || legal) route = 'person';
else if (['billing', 'complaint', 'booking_change'].includes(category)) { route = 'person'; reasons.push(category + '_goes_to_a_person'); }
else if (!o.draft_reply) route = o.reply_needed ? 'person' : 'no_action';
else {
  // The draft must stand on the FAQ alone: real ids, no contact details or links, and only numbers the cited answers contain.
  const d = String(o.draft_reply); const ids = o.faq_ids.filter((i) => faq[i]);
  const cited = ids.map((i) => faq[i]).join(' ');
  const strays = (d.match(/\d+(?:[.,]\d+)?/g) || []).filter((n) => !cited.includes(n));
  if (!ids.length || ids.length !== o.faq_ids.length) reasons.push('draft_refused: no valid FAQ source');
  else if (/(https?:\/\/|www\.|[\w.+-]+@[\w-]+\.[\w.]+|\+?\d[\d ]{7,}\d)/i.test(d)) reasons.push('draft_refused: contains a link or contact details');
  else if (strays.length) reasons.push('draft_refused: numbers not in the FAQ (' + strays.join(', ') + ')');
  else if (d.length > 1200) reasons.push('draft_refused: too long');
  if (reasons.some((r) => r.startsWith('draft_refused'))) route = 'person';
  else { route = 'draft_for_approval'; draft = { to: v.from_email, subject: 'Re: ' + v.subject, body: d, faq_ids: ids }; }
}
return [{ json: { message_id: v.message_id, from_email: v.from_email, subject: v.subject, category, urgency, route, reasons, draft,
  summary: ok ? String(o.summary || '').slice(0, 300) : v.subject.slice(0, 300), ai_status: ok ? 'ok' : reasons[0], dry_run: v.dry_run } }];
